     1→/**
     2→ * Multi-Paradigm Outcome Classifier
     3→ *
     4→ * Classifies outcomes based on how many paradigms say "utopia" vs "dystopia".
     5→ * Don't force single answer - show paradigm conflicts!
     6→ *
     7→ * **Thresholds:**
     8→ * - Utopia: ≥80/100
     9→ * - Dystopia: ≤30/100
    10→ * - Hybrid: 30-80
    11→ *
    12→ * **Examples:**
    13→ * - "Development Utopia, Liberal Dystopia" (Singapore: Dev 94, Western 22)
    14→ * - "Ecological Dystopia, Liberal/Development Utopia" (Norway: Eco 25, Western 93, Dev 98)
    15→ * - "Multi-Paradigm Dystopia" (Yemen: all <30)
    16→ * - "All-Four Utopia" (extremely rare, 0.5% of runs)
    17→ *
    18→ * @module data/aggregators/outcomeClassifier
    19→ */
    20→
    21→import type { MultiParadigmOutcomeClassification } from '@/types/multiParadigmDUI';
    22→
    23→/**
    24→ * Classify multi-paradigm outcome
    25→ *
    26→ * @param scores - 4 paradigm scores (0-100)
    27→ * @returns Outcome classification
    28→ */
    29→export function classifyOutcome(scores: {
    30→  western: number;
    31→  development: number;
    32→  ecological: number;
    33→  indigenous: number;
    34→}): MultiParadigmOutcomeClassification {
    35→  const UTOPIA_THRESHOLD = 80;
    36→  const DYSTOPIA_THRESHOLD = 30;
    37→
    38→  const { western, development, ecological, indigenous } = scores;
    39→
    40→  // Count utopias and dystopias
    41→  const utopias: string[] = [];
    42→  const dystopias: string[] = [];
    43→  const hybrids: string[] = [];
    44→
    45→  if (western >= UTOPIA_THRESHOLD) utopias.push('Western Liberal');
    46→  else if (western <= DYSTOPIA_THRESHOLD) dystopias.push('Western Liberal');
    47→  else hybrids.push('Western Liberal');
    48→
    49→  if (development >= UTOPIA_THRESHOLD) utopias.push('Development');
    50→  else if (development <= DYSTOPIA_THRESHOLD) dystopias.push('Development');
    51→  else hybrids.push('Development');
    52→
    53→  if (ecological >= UTOPIA_THRESHOLD) utopias.push('Ecological');
    54→  else if (ecological <= DYSTOPIA_THRESHOLD) dystopias.push('Ecological');
    55→  else hybrids.push('Ecological');
    56→
    57→  if (indigenous >= UTOPIA_THRESHOLD) utopias.push('Indigenous');
    58→  else if (indigenous <= DYSTOPIA_THRESHOLD) dystopias.push('Indigenous');
    59→  else hybrids.push('Indigenous');
    60→
    61→  const utopiasCount = utopias.length;
    62→  const dystopiasCount = dystopias.length;
    63→  const contested = utopiasCount > 0 && dystopiasCount > 0;
    64→
    65→  // Generate label
    66→  let label: string;
    67→
    68→  if (utopiasCount === 4) {
    69→    label = 'All-Four Utopia (extremely rare)';
    70→  } else if (dystopiasCount === 4) {
    71→    label = 'Multi-Paradigm Dystopia';
    72→  } else if (contested) {
    73→    // Contested: some utopias, some dystopias
    74→    const utopiaStr = utopias.join('/');
    75→    const dystopiaStr = dystopias.join('/');
    76→    label = `${utopiaStr} Utopia, ${dystopiaStr} Dystopia`;
    77→  } else if (utopiasCount > 0) {
    78→    // Utopias but no dystopias (all others hybrid)
    79→    const utopiaStr = utopias.join('/');
    80→    label = `${utopiaStr} Utopia`;
    81→  } else if (dystopiasCount > 0) {
    82→    // Dystopias but no utopias (all others hybrid)
    83→    const dystopiaStr = dystopias.join('/');
    84→    label = `${dystopiaStr} Dystopia`;
    85→  } else {
    86→    // All hybrids
    87→    label = 'Multi-Paradigm Hybrid (no clear utopia or dystopia)';
    88→  }
    89→
    90→  return {
    91→    utopiasCount,
    92→    dystopiasCount,
    93→    contested,
    94→    label,
    95→  };
    96→}
    97→
    98→/**
    99→ * Get paradigm outcome details
   100→ *
   101→ * @param scores - 4 paradigm scores (0-100)
   102→ * @returns Breakdown by paradigm
   103→ */
   104→export function getParadigmOutcomes(scores: {
   105→  western: number;
   106→  development: number;
   107→  ecological: number;
   108→  indigenous: number;
   109→}): {
   110→  western: 'utopia' | 'hybrid' | 'dystopia';
   111→  development: 'utopia' | 'hybrid' | 'dystopia';
   112→  ecological: 'utopia' | 'hybrid' | 'dystopia';
   113→  indigenous: 'utopia' | 'hybrid' | 'dystopia';
   114→} {
   115→  const UTOPIA_THRESHOLD = 80;
   116→  const DYSTOPIA_THRESHOLD = 30;
   117→
   118→  const classify = (score: number): 'utopia' | 'hybrid' | 'dystopia' => {
   119→    if (score >= UTOPIA_THRESHOLD) return 'utopia';
   120→    if (score <= DYSTOPIA_THRESHOLD) return 'dystopia';
   121→    return 'hybrid';
   122→  };
   123→
   124→  return {
   125→    western: classify(scores.western),
   126→    development: classify(scores.development),
   127→    ecological: classify(scores.ecological),
   128→    indigenous: classify(scores.indigenous),
   129→  };
   130→}
   131→
   132→/**
   133→ * Get dominant outcome (if exists)
   134→ *
   135→ * @param outcomes - Outcome classification
   136→ * @returns Dominant outcome, or 'contested' if paradigms disagree
   137→ */
   138→export function getDominantOutcome(
