    assert.ok(outcome.utopiasCount >= 0 && outcome.utopiasCount <= 4, 'Utopias count should be 0-4');
    assert.ok(outcome.dystopiasCount >= 0 && outcome.dystopiasCount <= 4, 'Dystopias count should be 0-4');

