          console.log(`      Development: ${paradigmScores.development.toFixed(1)}/100`);
          console.log(`      Ecological: ${paradigmScores.ecological.toFixed(1)}/100`);
          console.log(`      Indigenous: ${paradigmScores.indigenous.toFixed(1)}/100\n`);
