     1→/**
     2→ * Quality of Life Phase
     3→ *
     4→ * Updates multi-dimensional quality of life systems and calculates aggregate QoL
     5→ * Order: 34.0 (after social stability)
     6→ */
     7→
     8→import { SimulationPhase, PhaseResult, RNGFunction } from '../PhaseOrchestrator';
     9→import { GameState } from '@/types/game';
    10→import { updateQualityOfLifeSystems, calculateQualityOfLife } from '../../calculations';
    11→
    12→export class QualityOfLifePhase implements SimulationPhase {
    13→  readonly id = 'quality-of-life';
    14→  readonly name = 'Quality of Life Systems';
    15→  readonly order = 34.0;
    16→
    17→  execute(state: GameState, rng: RNGFunction): PhaseResult {
    18→    // Update multi-dimensional quality of life systems
    19→    const updatedQoLSystems = updateQualityOfLifeSystems(state);
    20→    state.qualityOfLifeSystems = updatedQoLSystems;
    21→
    22→    // Calculate aggregate quality of life from systems
    23→    const qualityOfLife = calculateQualityOfLife(updatedQoLSystems);
    24→    state.globalMetrics = {
    25→      ...state.globalMetrics,
    26→      qualityOfLife
    27→    };
