  );

  return (
    meaningfulWorkRatio * 0.4 +
    avgAlignment * 0.3 +
    recognitionLevel * 0.3
  );
}

function calculateSocialConnection(state: GameState): number {
  const collaborationOpportunities = (
    (1 - state.government.aiControl) * 0.5 +
