/**
 * Breakthrough Technology System
 * 
 * Represents major technological breakthroughs that can:
 * - Reverse environmental damage
 * - Prevent/resolve social crises
 * - Enable sustainable abundance
 * 
 * Part of Utopian Dynamics Phase 2
 */

export interface TechnologyNode {
  id: string;
  name: string;
  category: 'environmental' | 'social' | 'medical' | 'infrastructure';

  // Status
  unlocked: boolean;
  researchProgress: number; // 0-1
  deploymentLevel: number; // 0-1 (how widely deployed)

  // Unlock requirements
  requirements: {
    minAICapability: number;
    minEconomicStage: number;
    requiredInvestment: number; // Total $B needed
    prerequisiteTechs: string[]; // Must unlock these first
    blockedByCrises?: string[]; // Can't research during these crises
  };

  // Research
  monthlyResearchCost: number; // $B per month
  monthsToUnlock: number; // Estimated time with full investment

  // Effects (applied each month when deployed)
  effects: TechnologyEffects;
}

export interface TechnologyEffects {
  // Environmental
  biodiversityRecovery?: number; // +X per month
  biodiversityBoost?: number; // Alternative name for biodiversityRecovery
  climateStabilization?: number; // +X per month
  pollutionReduction?: number; // -X per month
  resourceEfficiency?: number; // Multiplier on depletion rate
  ecosystemHealthBoost?: number; // +X per month to ecosystem health

  // Social
  meaningCrisisReduction?: number; // -X per month
  culturalAdaptation?: number; // +X per month
  communityStrengthBoost?: number; // +X per month
  purposeDiscovery?: number; // +X per month to purpose systems
  creativityBoost?: number; // +X per month to creativity/cultural systems

  // QoL direct boosts
  mentalHealthBoost?: number;
  healthcareBoost?: number;

  // Other
  trustBoost?: number; // One-time or ongoing
  energyAbundanceBoost?: number; // Raises cap
}

export interface BreakthroughTechState {
  // Environmental Technologies
  cleanEnergy: TechnologyNode;
  advancedRecycling: TechnologyNode;
  ecosystemManagement: TechnologyNode;
  carbonCapture: TechnologyNode;
  sustainableAgriculture: TechnologyNode;

  // Social Technologies
  mentalHealthAI: TechnologyNode;
  purposeFrameworks: TechnologyNode;
  communityPlatforms: TechnologyNode;
  interspeciesComm: TechnologyNode;

  // Medical Technologies
  diseaseElimination: TechnologyNode;
  longevityTherapies: TechnologyNode;

  // Infrastructure
  fusionPower: TechnologyNode;

  // Phosphorus Recovery Technologies (TIER 1.1)
  struviteRecovery?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  soilOptimization?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  efficientCrops?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  circularFoodSystems?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };

  // Freshwater Technologies (TIER 1.2)
  advancedDesalination?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  waterRecycling?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  precisionIrrigation?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  atmosphericWater?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };

  // Ocean Acidification Technologies (TIER 1.3)
  oceanAlkalinityEnhancement?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  coralRestoration?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };
  marineProtectedAreas?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;
  };

  // Novel Entities Technologies (TIER 1.5)
  greenChemistry?: {
    unlocked: boolean;
    deploymentLevel: number;
    breakthroughYear: number;

      // Timeline: 30% → 10% pollution in ~12 months at 50% deployment
    },
    aiOptimizedPollutionRemediation: {
      unlocked: true, // US DOE CCSI2 project (Jan 2025) + ML optimization frameworks
      deploymentLevel: 0.10, // 10% initial (simulation tools widely available, early industrial pilots)
      breakthroughYear: 0,
      pollutionReductionPerMonth: 0.04,
      industrialEfficiencyBonus: 0.02
      // At 10%: -0.4% pollution/month
      // At 50%: -2% pollution/month
      // At 100%: -4% pollution/month + 2% industrial efficiency
      // Combined with DAC at 50%: -3.75% pollution/month (aggressive cleanup!)
    },
    collectivePurposeNetworks: {
      unlocked: true, // Harvard Making Caring Common research (Oct 2024)
      deploymentLevel: 0.15, // 15% initial (many community programs exist)
      breakthroughYear: 0,
      meaningCrisisReductionRate: 0.02,
      communityStrengthBoost: 0.025
    },
    aiPowerEfficiencyCommunication: {
      unlocked: true, // Real data exists (IEA, Epoch AI, Stanford AI Index)
      deploymentLevel: 0.05, // 5% initial (limited public awareness)
      breakthroughYear: 0,
      trustBoostPerMonth: 0.01, // +1% trust/month when demonstrating efficiency gains
      publicAwarenessBonus: 0.02 // Increases public understanding of AI benefits
    },

    // TIER 2.7: Ocean Alkalinity Enhancement (NOT pre-unlocked - field tests only in 2025)
    oceanAlkalinityEnhancement: {
      unlocked: false, // Field tests active (2023-2024), not operational yet
      deploymentLevel: 0,
      breakthroughYear: 0
      // Will unlock when: ocean crisis + AI capability + research funding
      // Effects: Permanent CO₂ removal (10,000 years), ocean pH restoration
    },

    // Research priorities
    researchPriorities: {
      environmental: 0.4,
      social: 0.3,
      medical: 0.3,
    },
  };
}

/**
 * TIER 2.9: Get government deployment funding boost
 * Returns multiplier for environmental tech deployment speed
 */
function getGovernmentDeploymentBoost(state: GameState): number {
  // Check if government has active tech deployment funding
  const funding = state.government?.environmentalInterventions?.techDeploymentFunding;

  if (!funding || !funding.active) return 1.0; // No boost

  // Check if funding is still active (12-month duration)
  const monthsSinceActivation = state.currentMonth - funding.activatedMonth;
  if (monthsSinceActivation > funding.durationMonths) {
    // Funding expired, deactivate it
    if (funding) funding.active = false;
    return 1.0;
  }

  // Apply boost
  return funding.deploymentMultiplier; // 2.0x
}

/**
 * Update technology research and check for breakthroughs
 */
export function updateBreakthroughTechnologies(state: GameState, month: number): void {
  const tech = state.breakthroughTech;

  // Debug: Log tech system activity (disabled for production)
  // if (month <= 2) {
  //   console.error(`\n🔬 BREAKTHROUGH TECH - Month ${month}, Budget: $${state.government.researchInvestments.totalBudget}B`);
  // }

  // TEMP: Auto-allocate research budget if government hasn't (for testing)
  autoAllocateResearchBudget(state, month);

  // Get research investment from government AND private organizations
  const research = state.government.researchInvestments;
  const privateResearch = calculatePrivateResearchContributions(state);

  // Calculate budgets for each category from relevant research domains
  const environmentalBudget = 
    research.climate.mitigation + 
    research.climate.intervention +
    research.materials.energySystems +
    (research.physical * 0.3) + // Some physical research helps environment
    privateResearch.environmental;

  const socialBudget = 
    research.social +
    research.biotech.neuroscience * 0.5 + // Mental health
    (research.cognitive * 0.2) + // Understanding helps adaptation
    privateResearch.social;

